<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Chart.js Example</title>
  <style>
    #myChartContainer {
      width: 100%;
      max-width: 600px;
      margin: auto;
    }
  </style>
</head>
<body>
  <div id="myChartContainer">
    <canvas id="myChart"></canvas>
  </div>
  <script src="path/to/your/script.js"></script>
</body>
</html>
