```python
# Monolithic architecture
class Monolith:
    def __init__(self):
        self.modules = []

    def add_module(self, module):
        self.modules.append(module)

    def run(self):
        for module in self.modules:
            module.run()

# Microservices architecture
class Microservice:
    def __init__(self, name):
        self.name = name

    def run(self):
        print(f"Running {self.name} microservice")

class MicroservicesArchitecture:
    def __init__(self):
        self.microservices = []

    def add_microservice(self, microservice):
        self.microservices.append(microservice)

    def run(self):
        for microservice in self.microservices:
            microservice.run()

# Example usage
monolith = Monolith()
monolith.add_module(Microservice("Module 1"))
monolith.add_module(Microservice("Module 2"))
monolith.run()

microservices_architecture = MicroservicesArchitecture()
microservices_architecture.add_microservice(Microservice("Service 1"))
microservices_architecture.add_microservice(Microservice("Service 2"))
microservices_architecture.run()
```
